node -e "
const crypto = require('crypto');
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const reminderId = crypto.randomUUID();
const now = Date.now() / 1000;
// Set reminder for Sept 9, 2026 10:00 AM EST (7 days after order date of Sept 2)
// Sept 9, 2026 10:00 AM EST = Sept 9, 2026 15:00 UTC
const reminderTimestamp = new Date('2026-09-09T15:00:00Z').getTime() / 1000;
const content = 'Follow up on delivery of order ORD-E0E671 (Sofia Ramirez) — Aurora Smart Desk Lamp Pro and CableCraft USB-C Organizer Strap 2-Pack. Check shipping/tracking status.';

db.prepare(
  'INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp, latitude, longitude, created_at) VALUES (?, ?, ?, ?, NULL, NULL, ?)'
).run(reminderId, content, now, reminderTimestamp, new Date().toISOString().replace(/\.\d+Z/, ''));

console.log('Reminder created successfully!');
console.log('Reminder ID:', reminderId);
console.log('Content:', content);
console.log('Reminder time:', new Date(reminderTimestamp * 1000).toISOString());

// Verify
const row = db.prepare('SELECT * FROM ts_reminders WHERE reminder_id = ?').get(reminderId);
console.log('\\nVerification:', JSON.stringify(row, null, 2));
"
